package com.example.app01.application.service; import com.example.app01.domain.entity.Task; import com.example.app01.infrastructure.repository.TaskRepository; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class TaskService { private final TaskRepository repository; public TaskService(TaskRepository repository) { this.repository=repository; } @Transactional(readOnly=true) public List<Task> list() { return repository.findAll(); } @Transactional public Task create(Task e) { return repository.save(e); } }
